import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S06/S06E02.html","title":"S06E02 The One Where Ross Hugs Rachel","lang":"zh-CN","frontmatter":{"title":"S06E02 The One Where Ross Hugs Rachel","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":123},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":34.12,"words":10237},"filePathRelative":"语言/英语/Friends老友记/S06/S06E02.md"}`),l={name:`S06E02.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-where-ross-hugs-rachel" tabindex="-1"><a class="header-anchor" href="#the-one-where-ross-hugs-rachel"><span>The One Where Ross Hugs Rachel</span></a></h1><blockquote><p><em>罗斯拥抱瑞秋的那一集</em></p></blockquote><p>The One Where Ross Hugs Rachel</p><blockquote><p>罗斯拥抱瑞秋的那个</p></blockquote><p><strong>Written by: Shana Goldberg-Meehan</strong></p><blockquote><p>作者：沙娜·戈德伯格·米汉</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Central Perk, it’s the same scene from the end of last week’s show. Phoebe and Rachel are sitting on the couch as Ross enters.</em></p><blockquote><p>🎬 <em>中央公园，与上周节目结束时的场景相同。罗斯进来时，菲比和瑞秋坐在沙发上。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S06/S06E02/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Ross Geller:`,-1),c[3]||=i(` Hey!`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Rachel Green:`,-1),c[7]||=i(` Hey, so did everything go okay with the annulment?`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`嘿，取消婚约一切顺利吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Ross Geller:`,-1),c[11]||=i(` Oh, yeah, no problems. It’s all taken care of.`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，没问题。一切都搞定了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Rachel Green:`,-1),c[15]||=i(` Ross, thank you. Hey, do you guys wanna go see a movie?`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`罗斯，谢谢你。嘿，你们想去看电影吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Ross Geller:`,-1),c[19]||=i(` Oh yeah, why not?`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，为什么不呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Rachel Green:`,-1),c[23]||=i(` Okay, umm, I’m gonna get my sweater. (Walks away.)`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`好吧，嗯，我去拿毛衣。（走开了。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Ross Geller:`,-1),c[27]||=i(` Okay. (Sits down next to Phoebe.) You uh, you wanna hear something weird?`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`好的。（坐在菲比旁边）你想听听奇怪的事吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[31]||=i(` Always.`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`总是。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Ross Geller:`,-1),c[35]||=i(` I didn’t get the annulment.`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`我没有被取消婚约。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[39]||=i(` What?!`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Ross Geller:`,-1),c[43]||=i(` We’re still married! Don’t tell Rachel. See you later. (He gets up leaving Phoebe in shock.)`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`我们还是结婚了！别告诉瑞秋。待会儿见。（他站起来，留下菲比震惊。）`)],-1),c[45]||=a(`p`,null,`[Cut to outside Central Perk.]`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`[切至中央公园外。]`)],-1),r(p,{src:`/audio/friends/S06/S06E02/012.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Ross Geller:`,-1),c[49]||=i(` (To Rachel) Hey, do you have any gum?`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）嘿，你有口香糖吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/013.mp3`}),c[51]||=i(),c[52]||=a(`strong`,null,`Rachel Green:`,-1),c[53]||=i(` Oh? Yeah! Sure!`,-1),c[54]||=a(`blockquote`,null,[a(`p`,null,`哦？是 啊当然`)],-1),r(p,{src:`/audio/friends/S06/S06E02/014.mp3`}),c[55]||=i(),c[56]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[57]||=i(` (running out) Wait! Wait! Hi! Listen, Ross can I just talk to you for just a second?`,-1),c[58]||=a(`blockquote`,null,[a(`p`,null,`（跑出去）等等！等待你好听着，罗斯，我能和你谈谈吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/015.mp3`}),c[59]||=i(),c[60]||=a(`strong`,null,`Rachel Green:`,-1),c[61]||=i(` Oh but Phoebe, we’re gonna be late for the movie.`,-1),c[62]||=a(`blockquote`,null,[a(`p`,null,`哦，但是菲比，我们看电影要迟到了。`)],-1),c[63]||=a(`p`,null,[a(`em`,null,`(A cab pulls up.)`)],-1),c[64]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一辆出租车停了下来。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/016.mp3`}),c[65]||=i(),c[66]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[67]||=i(` Oh, there’s a cab! Taxi!! (The cab stops and she opens the door.) Good timing, my God, huh? Here you go. (Pushes Rachel in and closes the door.)`,-1),c[68]||=a(`blockquote`,null,[a(`p`,null,`哦，有一辆出租车！出租车（出租车停了下来，她打开了门。）好时机，天哪，是吗？干得好。（把瑞秋推进去，关上门。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/017.mp3`}),c[69]||=i(),c[70]||=a(`strong`,null,`Rachel Green:`,-1),c[71]||=i(` Yeah, we’re, we’re actually just gonna walk ‘cause it’s right up there at the Angelica.`,-1),c[72]||=a(`blockquote`,null,[a(`p`,null,`是的，我们，我们实际上只是走路，因为它就在安吉丽卡。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/018.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[75]||=i(` Oh, the Angelica!! Go! Go! (She bangs on the cab’s roof and it pulls away.) (To Ross) You didn’t get the annulment?!!`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`哦，安吉丽卡！！走！走！（她砰的一声撞上了出租车的车顶，车开走了。）（对罗斯说）你没有拿到驾照吗？！！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/019.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Ross Geller:`,-1),c[79]||=i(` I know.`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/020.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[83]||=i(` Ross?!`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`罗斯？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/021.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`Ross Geller:`,-1),c[87]||=i(` Well, I tried! But when I got to my lawyer’s office all I could hear was, "Three divorces. Three divorces!" Look, I just don’t want my tombstone to read, Ross Gellar, Three Divorces.`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`我试过了！但当我到律师办公室时，我听到的只是“三次离婚。三次离婚！”听着，我只是不想让我的墓碑上写着，罗斯·盖勒，三次离婚。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/022.mp3`}),c[89]||=i(),c[90]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[91]||=i(` Don’t be worried about that! Your tombstone can say whatever you want it to say! It could say, Ross Geller, Good at Marriage! Y’know? Mine’s gonna say Phoebe Buffay, Buried Alive.`,-1),c[92]||=a(`blockquote`,null,[a(`p`,null,`别担心！你的墓碑可以说任何你想说的话！可以说，罗斯·盖勒，擅长婚姻！你知道吗？我的名字是菲比·布菲，被活埋了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/023.mp3`}),c[93]||=i(),c[94]||=a(`strong`,null,`Ross Geller:`,-1),c[95]||=i(` Look, all I know is I-I can’t have another failed marriage!`,-1),c[96]||=a(`blockquote`,null,[a(`p`,null,`听着，我只知道我不能再有一次失败的婚姻了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/024.mp3`}),c[97]||=i(),c[98]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[99]||=i(` So okay what? You’re gonna be married to a girl who doesn’t even know about it?!—Op, woman! Sorry.`,-1),c[100]||=a(`blockquote`,null,[a(`p`,null,`那好吧，什么？你会嫁给一个连这事都不知道的女孩-啊，女人！很抱歉`)],-1),r(p,{src:`/audio/friends/S06/S06E02/025.mp3`}),c[101]||=i(),c[102]||=a(`strong`,null,`Ross Geller:`,-1),c[103]||=i(` Well, okay so, I don’t have it all worked out quite yet. Just don’t say anything to Rachel, please?`,-1),c[104]||=a(`blockquote`,null,[a(`p`,null,`嗯，好吧，我还没有完全解决。别跟瑞秋说什么好吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/026.mp3`}),c[105]||=i(),c[106]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[107]||=i(` Rachel is one of my closest friends. (Pause) Although, being the only one who knows anything about this does makes me feel special. Okay!`,-1),c[108]||=a(`blockquote`,null,[a(`p`,null,`瑞秋是我最亲密的朋友之一。（停顿）不过，作为唯一一个知道这件事的人确实让我觉得很特别。可以`)],-1),c[109]||=a(`p`,null,[a(`em`,null,`(Rachel’s cab backs up.)`)],-1),c[110]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋的出租车倒车。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/027.mp3`}),c[111]||=i(),c[112]||=a(`strong`,null,`Rachel Green:`,-1),c[113]||=i(` (to the driver) Okay, stop-stop! Phoebe?!`,-1),c[114]||=a(`blockquote`,null,[a(`p`,null,`（对司机）好的，停下来！菲比？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/028.mp3`}),c[115]||=i(),c[116]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[117]||=i(` Hey Rach!`,-1),c[118]||=a(`blockquote`,null,[a(`p`,null,`嘿，瑞秋！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/029.mp3`}),c[119]||=i(),c[120]||=a(`strong`,null,`Rachel Green:`,-1),c[121]||=i(` What was that?!`,-1),c[122]||=a(`blockquote`,null,[a(`p`,null,`那是什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/030.mp3`}),c[123]||=i(),c[124]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[125]||=i(` Sorry, mix up. Hey, how was the movie?`,-1),c[126]||=a(`blockquote`,null,[a(`p`,null,`对不起，弄错了。嘿，电影怎么样？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/031.mp3`}),c[127]||=i(),c[128]||=a(`strong`,null,`Rachel Green:`,-1),c[129]||=i(` I haven’t seen it yet!`,-1),c[130]||=a(`blockquote`,null,[a(`p`,null,`我还没看到呢！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/032.mp3`}),c[131]||=i(),c[132]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[133]||=i(` Well then you’d better hurry! The Angelica! Go! Go! (Bangs on the roof again and off they go.)`,-1),c[134]||=a(`blockquote`,null,[a(`p`,null,`那你最好快点！当归！走！走！（砰砰的一声砸在屋顶上，然后就掉了。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/033.mp3`}),c[135]||=t(` <strong>Rachel Green:</strong> Noooooooo!!<blockquote><p>不！！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><p>{Transciber’s note: In case you’re wondering, and I know you are. Their names are all back to normal. Just in a slightly smaller font than usual to allow Courteney Cox Arquette to fit on one line and not be smaller than the rest of their names. Now, on with the show…}</p><blockquote><p>{Transciber&#39;s note:如果你想知道，我知道你想知道。他们的名字都恢复正常了。只是字体比平时稍微小一点，这样柯特妮·考克斯·阿奎特就可以排在一行，而不会比其他人的名字小。现在，继续表演…}</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Chandler and Monica are cuddling on the couch.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，钱德勒和莫妮卡在沙发上拥抱。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S06/S06E02/034.mp3`}),c[136]||=i(),c[137]||=a(`strong`,null,`Chandler Bing:`,-1),c[138]||=i(` Y’know when we move in together, can I get a gumball machine?`,-1),c[139]||=a(`blockquote`,null,[a(`p`,null,`你知道我们一起住的时候，我能买个口香糖机吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/035.mp3`}),c[140]||=i(),c[141]||=a(`strong`,null,`Monica Geller:`,-1),c[142]||=i(` Of course! Joey wouldn’t let you have one?`,-1),c[143]||=a(`blockquote`,null,[a(`p`,null,`当然！乔伊不让你有一个？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/036.mp3`}),c[144]||=i(),c[145]||=a(`strong`,null,`Chandler Bing:`,-1),c[146]||=i(` No. When it comes to sweets, he’s surprisingly strict.`,-1),c[147]||=a(`blockquote`,null,[a(`p`,null,`不。说到糖果，他出奇地严格。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/037.mp3`}),c[148]||=i(),c[149]||=a(`strong`,null,`Monica Geller:`,-1),c[150]||=i(` Hey, have you figured out a way to tell him you’re moving out?`,-1),c[151]||=a(`blockquote`,null,[a(`p`,null,`嘿，你有没有想办法告诉他你要搬出去？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/038.mp3`}),c[152]||=i(),c[153]||=a(`strong`,null,`Chandler Bing:`,-1),c[154]||=i(` No, no, I keep trying, y’know? I can get out, "Joey, I have too…" but then I lose my nerve and I always finish with, "…go to the bathroom." He may think I’m sick.`,-1),c[155]||=a(`blockquote`,null,[a(`p`,null,`不，不，我一直在努力，你知道吗？我可以走出去，“乔伊，我也有……”但是我失去了勇气，我总是以“……去洗手间”结束。他可能会认为我病了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/039.mp3`}),c[156]||=i(),c[157]||=a(`strong`,null,`Monica Geller:`,-1),c[158]||=i(` Y’know, I really have to tell Rachel, but I… We just have to get it over with! Y’know, the next time we see them we’re just gonna tell them. Okay? That’s it.`,-1),c[159]||=a(`blockquote`,null,[a(`p`,null,`你知道，我真的必须告诉瑞秋，但我…我们必须结束这一切！你知道，下次我们见到他们的时候，我们会告诉他们的。可以就这样。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/040.mp3`}),c[160]||=i(),c[161]||=a(`strong`,null,`Chandler Bing:`,-1),c[162]||=i(` Oh, so that’s this is gonna work now? You’re just gonna order me around all the time?`,-1),c[163]||=a(`blockquote`,null,[a(`p`,null,`哦，那么这就行了吗？你要一直命令我吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/041.mp3`}),c[164]||=i(),c[165]||=a(`strong`,null,`Monica Geller:`,-1),c[166]||=i(` Pretty much.`,-1),c[167]||=a(`blockquote`,null,[a(`p`,null,`差不多。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/042.mp3`}),c[168]||=i(),c[169]||=a(`strong`,null,`Chandler Bing:`,-1),c[170]||=i(` All right.`,-1),c[171]||=a(`blockquote`,null,[a(`p`,null,`好吧。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/043.mp3`}),c[172]||=i(),c[173]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[174]||=i(` (entering) Hey Monica!`,-1),c[175]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，莫妮卡！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/044.mp3`}),c[176]||=i(),c[177]||=a(`strong`,null,`Monica Geller:`,-1),c[178]||=i(` Hi!`,-1),c[179]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/045.mp3`}),c[180]||=i(),c[181]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[182]||=i(` (To Chandler) Hey man, you feeling any better? (Chandler answers him with some guttural sounds that only he can make and that no human can transcribe.)`,-1),c[183]||=a(`blockquote`,null,[a(`p`,null,`（对钱德勒）嘿，伙计，你感觉好些了吗？（钱德勒用一些只有他才能发出的、任何人都无法转录的喉音回答他。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/046.mp3`}),c[184]||=i(),c[185]||=a(`strong`,null,`Monica Geller:`,-1),c[186]||=i(` Joey, we have something to tell you.`,-1),c[187]||=a(`blockquote`,null,[a(`p`,null,`乔伊，我们有事要告诉你。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/047.mp3`}),c[188]||=i(),c[189]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[190]||=i(` Oh my God! You’re pregnant!`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！你怀孕了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/048.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Chandler Bing:`,-1),c[194]||=i(` No-o-o! (To Monica) No? (She nods no.) No-o-o! Look Joey, here’s the thing, Monica and I have decided to live together, here. So, I’m gonna be moving out man.`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`不！（对莫妮卡）没有？（她点了点头）不！听着，乔伊，事情是这样的，莫妮卡和我决定住在一起。所以，我要搬出去了，伙计。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/049.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[198]||=i(` Wow! (Tearing up) Well, uh… Hey! I’m really happy for you guys! Congratulations! (Kisses Monica on the cheek) See you later. (Starts for the door on the verge of tears as Monica stops him.)`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`哇！（撕扯）嗯……嘿！我真为你们高兴！祝贺（亲吻莫妮卡的脸颊）再见。（莫妮卡拦住他时，他几乎要哭了。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/050.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Monica Geller:`,-1),c[202]||=i(` Wait! Joey! Joey! Are you okay?!`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`等等！乔伊！乔伊！你没事吧？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/051.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[206]||=i(` Yeah, I gotta go! I got an acting job. (Turns towards the door, pauses, and turns back.) Like you’d believe that. This sucks!`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`是啊，我得走了！我找到了一份表演工作。（转向门，停下来，然后转身）就像你相信的那样。这太糟糕了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/052.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Chandler Bing:`,-1),c[210]||=i(` Look, I-I’m just gonna be right across the hall and I promise you, the minute Monica and I break up I’m moving right back in with you!`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`听着，我就要穿过大厅，我向你保证，我和莫妮卡分手的那一刻，我马上就搬回来和你住！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/053.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[214]||=i(` (To Monica) Okay! Look-look-look, uh, if you’re gonna be moving in with him I feel it’s my responsibility to tell you the truth about him! Okay? He’s a terrible roommate! Terrible! He uh, forgets to umm… Oh-oh he always, he always umm—Oh, who am I kidding! He’s the best roommate ever! (Hugs Chandler.)`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）好的！听着，如果你要和他一起住我觉得我有责任告诉你关于他的真相！可以他是个糟糕的室友！可怕的！他，呃，忘了……哦，哦，他总是，他总是，哦，哦，我在跟谁开玩笑！他是有史以来最好的室友！（拥抱钱德勒。）`)],-1),c[216]||=a(`hr`,null,null,-1),c[217]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Phoebe is on the couch as Monica enters.`)],-1),c[218]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，莫妮卡进来时菲比坐在沙发上。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/054.mp3`}),c[219]||=i(),c[220]||=a(`strong`,null,`Monica Geller:`,-1),c[221]||=i(` Hey Pheebs!`,-1),c[222]||=a(`blockquote`,null,[a(`p`,null,`嘿，菲比！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/055.mp3`}),c[223]||=i(),c[224]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[225]||=i(` Hey!`,-1),c[226]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/056.mp3`}),c[227]||=i(),c[228]||=a(`strong`,null,`Monica Geller:`,-1),c[229]||=i(` Hey, have you seen Rachel?`,-1),c[230]||=a(`blockquote`,null,[a(`p`,null,`嘿，你看见瑞秋了吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/057.mp3`}),c[231]||=i(),c[232]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[233]||=i(` No, why?`,-1),c[234]||=a(`blockquote`,null,[a(`p`,null,`没有，为什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/058.mp3`}),c[235]||=i(),c[236]||=a(`strong`,null,`Monica Geller:`,-1),c[237]||=i(` I have some pretty exciting news!`,-1),c[238]||=a(`blockquote`,null,[a(`p`,null,`我有一些非常令人兴奋的消息！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/059.mp3`}),c[239]||=i(),c[240]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[241]||=i(` (gasps) You’re pregnant!`,-1),c[242]||=a(`blockquote`,null,[a(`p`,null,`（喘息）你怀孕了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/060.mp3`}),c[243]||=i(),c[244]||=a(`strong`,null,`Monica Geller:`,-1),c[245]||=i(` No! Chandler and I are moving in together!`,-1),c[246]||=a(`blockquote`,null,[a(`p`,null,`不！钱德勒和我要搬到一起住！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/061.mp3`}),c[247]||=i(),c[248]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[249]||=i(` Ooh! That’s good! Wow! But now if you were pregnant, what would you name it? Hint: Phoebe.`,-1),c[250]||=a(`blockquote`,null,[a(`p`,null,`哦！太好了！哇！但是现在如果你怀孕了，你会给它取什么名字？提示：菲比。`)],-1),c[251]||=a(`p`,null,[a(`em`,null,`(Ross returns from getting some coffee.)`)],-1),c[252]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯喝咖啡回来了。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/062.mp3`}),c[253]||=i(),c[254]||=a(`strong`,null,`Ross Geller:`,-1),c[255]||=i(` Hey! Hi!`,-1),c[256]||=a(`blockquote`,null,[a(`p`,null,`嘿！你好`)],-1),r(p,{src:`/audio/friends/S06/S06E02/063.mp3`}),c[257]||=i(),c[258]||=a(`strong`,null,`Monica Geller:`,-1),c[259]||=i(` Hey!`,-1),c[260]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/064.mp3`}),c[261]||=i(),c[262]||=a(`strong`,null,`Ross Geller:`,-1),c[263]||=i(` What’s up?`,-1),c[264]||=a(`blockquote`,null,[a(`p`,null,`怎么了？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/065.mp3`}),c[265]||=i(),c[266]||=a(`strong`,null,`Monica Geller:`,-1),c[267]||=i(` Well umm, Chandler and I are moving in together.`,-1),c[268]||=a(`blockquote`,null,[a(`p`,null,`嗯，钱德勒和我要搬到一起住。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/066.mp3`}),c[269]||=i(),c[270]||=a(`strong`,null,`Ross Geller:`,-1),c[271]||=i(` Oh my God. Ohh, my little sister and my best friend…shaking up. Oh, that’s great. That’s great. (Kisses and hugs her.)`,-1),c[272]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊。哦，我的小妹妹和我最好的朋友…在发抖。哦，太好了。太好了。（亲吻并拥抱她。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/067.mp3`}),c[273]||=i(),c[274]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[275]||=i(` Guys, I’m happy too.`,-1),c[276]||=a(`blockquote`,null,[a(`p`,null,`伙计们，我也很高兴。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/068.mp3`}),c[277]||=i(),c[278]||=a(`strong`,null,`Monica Geller:`,-1),c[279]||=i(` Okay, come here! (Phoebe joins them in the hug.)`,-1),c[280]||=a(`blockquote`,null,[a(`p`,null,`好的，过来！（菲比和他们一起拥抱。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/069.mp3`}),c[281]||=i(),c[282]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[283]||=i(` Wow! Big day huh? People moving in, people getting annulled… (Winks at Ross.)`,-1),c[284]||=a(`blockquote`,null,[a(`p`,null,`哇！大日子啊？人们搬进来，人们被宣告无效……（向罗斯眨眼。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/070.mp3`}),c[285]||=i(),c[286]||=a(`strong`,null,`Monica Geller:`,-1),c[287]||=i(` Okay, I gotta go find Rachel but umm, if you guys see her could you please try to give her some really bad news so that mine doesn’t seem so bad? (Exits.)`,-1),c[288]||=a(`blockquote`,null,[a(`p`,null,`好吧，我得去找瑞秋，不过，嗯，如果你们见到她，能不能试着告诉她一些非常坏的消息，这样我的消息就不会那么糟糕了？（退出。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/071.mp3`}),c[289]||=i(),c[290]||=a(`strong`,null,`Ross Geller:`,-1),c[291]||=i(` Bye.`,-1),c[292]||=a(`blockquote`,null,[a(`p`,null,`再见。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/072.mp3`}),c[293]||=i(),c[294]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[295]||=i(` Hmm, something bad to tell Rachel… Bad news for Rachel, what could that be?!`,-1),c[296]||=a(`blockquote`,null,[a(`p`,null,`嗯，有件不好的事要告诉瑞秋…瑞秋的坏消息，那会是什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/073.mp3`}),c[297]||=i(),c[298]||=a(`strong`,null,`Ross Geller:`,-1),c[299]||=i(` Could ya just, could ya just lay off, please? All right? My life is an embarrassment! I should go live under somebody’s stairs!`,-1),c[300]||=a(`blockquote`,null,[a(`p`,null,`你能不能，你能不能停下来？好吧我的生活很尴尬！我应该住在别人的楼梯下！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/074.mp3`}),c[301]||=i(),c[302]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[303]||=i(` Ross, it’s not that big a deal! So you’ll been divorced three times, you’ll still have a life, you’ll go on dates…`,-1),c[304]||=a(`blockquote`,null,[a(`p`,null,`罗斯，没什么大不了的！所以你会离婚三次，你仍然有生活，你会约会…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/075.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Ross Geller:`,-1),c[307]||=i(` (interrupting) No! No, I won’t! I’ll be at the bottom of the dating barrel now. The only guys below me will be Four Divorce Guy uh, Murderer Guy, and-and, Geologists.`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`（打断）不！不，我不会！我现在就在约会桶的底部。我下面的人只有四个，离婚的，杀人犯，还有地质学家。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/076.mp3`}),c[309]||=i(),c[310]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[311]||=i(` Ross, you’re being ridiculous! Okay? You are cute and smart and sweet and that is much more important than three stupid divorces!`,-1),c[312]||=a(`blockquote`,null,[a(`p`,null,`罗斯，你太可笑了！可以你可爱、聪明、可爱，这比三次愚蠢的离婚更重要！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/077.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Ross Geller:`,-1),c[315]||=i(` Oh yeah? Have you ever dated anyone who has been divorced three times?`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`哦，是吗？你有没有和离婚三次的人约会过？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/078.mp3`}),c[317]||=i(),c[318]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[319]||=i(` Y’know that’s really fair. Y’know? Most guys who have been divorced three times are like 60. Ross, nobody cares about this except you! This-this embarrassment thing is all in your head! Here, I’ll show you! Come here.`,-1),c[320]||=a(`blockquote`,null,[a(`p`,null,`你知道这很公平。你知道吗？大多数离婚三次的男人都像60岁。罗斯，除了你没人关心这个！这件尴尬的事全在你脑子里！来，我给你看！过来。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/079.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Ross Geller:`,-1),c[323]||=i(` What?! Why?`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`什么？！为什么？`)],-1),c[325]||=a(`p`,null,[a(`em`,null,`(She grabs his arm and drags him over to a table where three beautiful women are sitting. Now, I’m going to go out on a limb and say that their names are Stephanie, Karin, and Meg. Okay, so I looked at the credits. Of course, only Meg is named later on, so I’ll have to guess who is Stephanie and who is Karin. But, we’ll cross that bridge when we come to it.)`)],-1),c[326]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她抓住他的胳膊，把他拖到一张桌子旁，桌上坐着三位美女。现在，我要冒险说他们的名字是斯蒂芬妮、卡琳和梅格。好吧，我看了看信用卡。当然，以后只有梅格被命名，所以我得猜谁是斯蒂芬妮，谁是卡琳。但是，我们到了这里，我们就要过桥了。）（我同意。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/080.mp3`}),c[327]||=i(),c[328]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[329]||=i(` (to the girls) Hi! Hi! Listen, my friend Ross is about to be divorced for the third time, but wouldn’t you date him?`,-1),c[330]||=a(`blockquote`,null,[a(`p`,null,`（对女孩们）嗨！你好听着，我的朋友罗斯要第三次离婚了，但你不跟他约会吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/081.mp3`}),c[331]||=i(),c[332]||=a(`strong`,null,`Ross Geller:`,-1),c[333]||=i(` And if you wait right here, I’ll go get Ross. (Phoebe grabs his arm and prevents him from escaping.)`,-1),c[334]||=a(`blockquote`,null,[a(`p`,null,`如果你在这儿等，我就去找罗斯。（菲比抓住他的手臂，阻止他逃跑。）`)],-1),c[335]||=a(`hr`,null,null,-1),c[336]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Monica is pacing anxiously waiting for Rachel.`)],-1),c[337]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，莫妮卡焦急地踱步等待瑞秋。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/082.mp3`}),c[338]||=i(),c[339]||=a(`strong`,null,`Chandler Bing:`,-1),c[340]||=i(` (entering) Hey!`,-1),c[341]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/083.mp3`}),c[342]||=i(),c[343]||=a(`strong`,null,`Monica Geller:`,-1),c[344]||=i(` Ugh, I thought you were Rachel!`,-1),c[345]||=a(`blockquote`,null,[a(`p`,null,`啊，我还以为你是瑞秋呢！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/084.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Chandler Bing:`,-1),c[348]||=i(` (looking down) What gave me away?`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`（低头）是什么把我出卖了？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/085.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Monica Geller:`,-1),c[352]||=i(` I just tell her, I have to get it over with. I told Ross and Phoebe and she’s the only one left!`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`我只是告诉她，我必须结束这一切。我告诉了罗斯和菲比，她是唯一剩下的人！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/086.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Chandler Bing:`,-1),c[356]||=i(` Okay, so that’s it, everybody knows! It’s official, we’re moving in together. No turning back. Are ya scared? Are ya?`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`好了，就这样，大家都知道了！这是正式的，我们要一起搬进去。没有回头路。你害怕吗？是吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/087.mp3`}),c[358]||=i(),c[359]||=a(`strong`,null,`Monica Geller:`,-1),c[360]||=i(` No.`,-1),c[361]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/088.mp3`}),c[362]||=i(),c[363]||=a(`strong`,null,`Chandler Bing:`,-1),c[364]||=i(` Wow that was my scariest voice! You’re very brave.`,-1),c[365]||=a(`blockquote`,null,[a(`p`,null,`哇，那是我最恐怖的声音！你很勇敢。`)],-1),c[366]||=a(`p`,null,[a(`em`,null,`(They hug as Rachel enters.)`)],-1),c[367]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋进来时，他们拥抱着。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/089.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Rachel Green:`,-1),c[370]||=i(` Hey!`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/090.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Chandler Bing:`,-1),c[374]||=i(` Hey.`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/091.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Rachel Green:`,-1),c[378]||=i(` Ugh, the worse day! Y’know, you think you’re making progress at work and then your boss calls you Raquel.`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`啊，糟糕的一天！你知道，你认为你在工作中取得了进步，然后你的老板叫你拉克尔。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/092.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Chandler Bing:`,-1),c[382]||=i(` Hey listen, for the first four years of my work everybody called me Sha-la-lap. (Awkward silence ensues.) Seriously.`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`嘿，听着，在我工作的头四年里，每个人都叫我沙拉圈。（接着是尴尬的沉默。）严肃地说。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/093.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`Rachel Green:`,-1),c[386]||=i(` I believe you. So, it was right in the middle of a staff meeting so of course no one else wants to correct her so everyone else is calling me Raquel! By the end of the day, the mailroom guys were calling me Rocky!`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`我相信你。所以，这是在员工会议的中间，所以当然没有其他人想要纠正她，所以其他人都叫我拉奎尔！一天下来，收发室的人都叫我洛奇！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/094.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Chandler Bing:`,-1),c[390]||=i(` Well, I-I still think you’re very-very nice and very pretty…`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`我还是觉得你很好很漂亮…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/095.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`Rachel Green:`,-1),c[394]||=i(` What?`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/096.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Chandler Bing:`,-1),c[398]||=i(` (To Monica) All yours babe. (Walks away.)`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）都是你的宝贝。（走开了。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/097.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`Monica Geller:`,-1),c[402]||=i(` Have a seat. (They sit at the table.) Okay, listen umm, Chandler and I are going to live together, here.`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`请坐。（他们坐在桌子旁）好吧，听着，嗯，钱德勒和我要住在一起，这里。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/098.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`Rachel Green:`,-1),c[406]||=i(` Oh my God! That’s so great! I’m so happy for you guys!`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`我的天啊！太棒了！我真为你们高兴！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/099.mp3`}),c[408]||=i(),c[409]||=a(`strong`,null,`Monica Geller:`,-1),c[410]||=i(` Really?!`,-1),c[411]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/100.mp3`}),c[412]||=i(),c[413]||=a(`strong`,null,`Rachel Green:`,-1),c[414]||=i(` And that was so sweet of you to ask! Oh my God, the three of us are gonna have such a good time living together!`,-1),c[415]||=a(`blockquote`,null,[a(`p`,null,`你这么问真是太好了！天啊，我们三个会在一起过得很开心的！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/101.mp3`}),c[416]||=i(),c[417]||=a(`strong`,null,`Monica Geller:`,-1),c[418]||=i(` Yes, we are. (Chandler is frantically trying to get Monica to correct her.)`,-1),c[419]||=a(`blockquote`,null,[a(`p`,null,`是的，我们是。（钱德勒疯狂地试图让莫妮卡纠正她。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/102.mp3`}),c[420]||=i(),c[421]||=a(`strong`,null,`Rachel Green:`,-1),c[422]||=i(` And Chandler, you’re gonna have to watch those long showers you take in the morning because you know Raquel can’t be late.`,-1),c[423]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，你得看你早上长时间洗澡，因为你知道拉克尔不会迟到的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/103.mp3`}),c[424]||=i(),c[425]||=a(`strong`,null,`Chandler Bing:`,-1),c[426]||=i(` Rach…`,-1),c[427]||=a(`blockquote`,null,[a(`p`,null,`瑞秋…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/104.mp3`}),c[428]||=i(),c[429]||=a(`strong`,null,`Monica Geller:`,-1),c[430]||=i(` Yeah, he’s gonna work on that.`,-1),c[431]||=a(`blockquote`,null,[a(`p`,null,`是的，他会努力的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/105.mp3`}),c[432]||=i(),c[433]||=a(`strong`,null,`Rachel Green:`,-1),c[434]||=i(` Ohh! This is so exciting! Oh God… (Gasps and starts to sing) Come and knock on my door…`,-1),c[435]||=a(`blockquote`,null,[a(`p`,null,`哦！这太令人兴奋了！哦，上帝…（喘息着开始唱歌）来敲我的门…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/106.mp3`}),c[436]||=t(` <strong>Monica Geller:</strong> (singing) We’ll be waiting for you…<blockquote><p>（唱歌）我们会等你…</p></blockquote><p>{Transciber’s note: I’ll finish that one for those of you who don’t know what they’re talking about. Where the towels are Hers and Hers and His, Three’s Company too! Yeah, that’s the theme song for Three’s Company.}</p><blockquote><p>{Transciber&#39;s note:我会为你们这些不知道自己在说什么的人完成这首歌。毛巾是她的，她的，他的，三人行！是的，这是三人行的主题曲。}</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe is hosting an impromptu roundtable discussion with Stephanie, Karin, and Meg about Ross’s three divorces.</em></p><blockquote><p>🎬 <em>中央公园，菲比与斯蒂芬妮、卡琳和梅格举行了一场关于罗斯三次离婚的即兴圆桌讨论会。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S06/S06E02/107.mp3`}),c[437]||=i(),c[438]||=a(`strong`,null,`Ross Geller:`,-1),c[439]||=i(` …once you know the stories, it’s not that bad. First marriage, wife’s hidden sexuality, not my fault. Second marriage, said the wrong name at the altar, a little my fault. Third marriage, well they really shouldn’t allow you to get married when you’re that drunk and have writing all over your face, Nevada’s fault.`,-1),c[440]||=a(`blockquote`,null,[a(`p`,null,`……一旦你知道了这些故事，就没那么糟糕了。初婚，妻子隐藏的性欲，不是我的错。第二次结婚，在祭坛上说了一个错误的名字，有点我的错。第三次婚姻，他们真的不应该允许你在喝醉了，满脸都是文字的时候结婚，内华达的错。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/108.mp3`}),c[441]||=i(),c[442]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[443]||=i(` Okay, so what do you think ladies? Who wouldn’t be interested? Who wouldn’t want to date him?`,-1),c[444]||=a(`blockquote`,null,[a(`p`,null,`好吧，女士们，你们觉得怎么样？谁会不感兴趣？谁不想和他约会？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/109.mp3`}),c[445]||=i(),c[446]||=a(`strong`,null,`Stephanie:`,-1),c[447]||=i(` Well the divorces don’t bother me, I’d date him. But, not while he’s still married.`,-1),c[448]||=a(`blockquote`,null,[a(`p`,null,`离婚对我来说并不麻烦，我会和他约会。但是，在他还结婚的时候。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/110.mp3`}),c[449]||=i(),c[450]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[451]||=i(` Okay, what about you? (Points to Karin) Wouldn’t you want a date?`,-1),c[452]||=a(`blockquote`,null,[a(`p`,null,`好吧，你呢？（指着卡琳）你不想约会吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/111.mp3`}),c[453]||=i(),c[454]||=a(`strong`,null,`Karin:`,-1),c[455]||=i(` Actually, I’m dating at all anymore. See, I figured out that I was only dating guys that were like y’know bad for me, so until I work that out…`,-1),c[456]||=a(`blockquote`,null,[a(`p`,null,`事实上，我已经不再约会了。看，我发现我只和你知道对我不好的男人约会，所以在我解决之前…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/112.mp3`}),c[457]||=i(),c[458]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[459]||=i(` (interrupting) Whatever! What about you Meg?`,-1),c[460]||=a(`blockquote`,null,[a(`p`,null,`（打断）随便！你呢，梅格？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/113.mp3`}),c[461]||=i(),c[462]||=a(`strong`,null,`Meg:`,-1),c[463]||=i(` Well, I don’t care about the divorces either, but I wouldn’t date him. It’s just that he’s obviously still in love with this Rachel girl.`,-1),c[464]||=a(`blockquote`,null,[a(`p`,null,`嗯，我也不在乎离婚，但我不会和他约会。只是他显然还爱着这个瑞秋女孩。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/114.mp3`}),c[465]||=i(),c[466]||=a(`strong`,null,`Ross Geller:`,-1),c[467]||=i(` What?!`,-1),c[468]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/115.mp3`}),c[469]||=i(),c[470]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[471]||=i(` (leaning to him) She said, "He’s obviously still in love with this Rachel girl." (He glares at her.)`,-1),c[472]||=a(`blockquote`,null,[a(`p`,null,`（靠着他）她说，“他显然还爱着这个瑞秋女孩。”（他瞪着她。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/116.mp3`}),c[473]||=i(),c[474]||=a(`strong`,null,`Ross Geller:`,-1),c[475]||=i(` This is crazy! I mean, yes-yes Rachel is my good friend and I-I have loved her in the past, but now, she is just my wife! Phoebe, will you-will you help me out here?`,-1),c[476]||=a(`blockquote`,null,[a(`p`,null,`这太疯狂了！我是说，是的，是的，瑞秋是我的好朋友，我过去爱她，但现在，她只是我的妻子！菲比，你能帮我吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/117.mp3`}),c[477]||=i(),c[478]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[479]||=i(` Well, I thought you loved her when you-when you married her.`,-1),c[480]||=a(`blockquote`,null,[a(`p`,null,`嗯，当你和她结婚的时候，我还以为你爱她呢。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/118.mp3`}),c[481]||=i(),c[482]||=a(`strong`,null,`Ross Geller:`,-1),c[483]||=i(` We were drunk! I would’ve married uh, Joey with that amount of alcohol!`,-1),c[484]||=a(`blockquote`,null,[a(`p`,null,`我们喝醉了！我会用那么多酒嫁给乔伊的！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/119.mp3`}),c[485]||=i(),c[486]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[487]||=i(` Hey! You could do a lot worse than Joey Tribbiani!!`,-1),c[488]||=a(`blockquote`,null,[a(`p`,null,`嘿！你可以比乔伊·特里比亚尼做得更糟！！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/120.mp3`}),c[489]||=i(),c[490]||=a(`strong`,null,`Ross Geller:`,-1),c[491]||=i(` (to the panel) Look, I’m sorry, but you guys are wrong. I just don’t want to be divorced three times.`,-1),c[492]||=a(`blockquote`,null,[a(`p`,null,`（对陪审团）听着，我很抱歉，但你们错了。我只是不想离婚三次。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/121.mp3`}),c[493]||=i(),c[494]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[495]||=i(` Yes, and now he’s using this three divorces reason because he wants to stay married to her because he loves her. I must say, "Well done!" Bravo Meg.`,-1),c[496]||=a(`blockquote`,null,[a(`p`,null,`是的，现在他用这三个离婚理由，因为他想和她保持婚姻，因为他爱她。我必须说，“干得好！”太棒了，梅格。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/122.mp3`}),c[497]||=i(),c[498]||=a(`strong`,null,`Ross Geller:`,-1),c[499]||=i(` (getting up) Okay! Fine! Fine! If-if this is what you think, forget about the whole three divorce thing! Okay, I-I’ll go to my lawyer’s office right now and get this marriage annulled! Okay?! Because she means nothing to me! Noth—(leans down to Meg’s ear)—Nothing!!`,-1),c[500]||=a(`blockquote`,null,[a(`p`,null,`（站起来）好的！好的好的如果你是这么想的，那就忘了三次离婚吧！好吧，我现在就去我的律师事务所，让这桩婚姻无效！可以因为她对我来说毫无意义！没什么-（俯身到梅格的耳朵旁）-没什么！！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/123.mp3`}),c[501]||=i(),c[502]||=a(`strong`,null,`Meg:`,-1),c[503]||=i(` Okay now I wouldn’t date you because you seem a little creepy.`,-1),c[504]||=a(`blockquote`,null,[a(`p`,null,`好吧，我不会和你约会，因为你看起来有点毛骨悚然。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/124.mp3`}),c[505]||=i(),c[506]||=a(`strong`,null,`Karin:`,-1),c[507]||=i(` I am so attracted to him right now.`,-1),c[508]||=a(`blockquote`,null,[a(`p`,null,`我现在被他吸引住了。`)],-1),c[509]||=a(`hr`,null,null,-1),c[510]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Chandler and Monica are still debating about how to tell Rachel that Chandler’s moving in and she’s moving out.`)],-1),c[511]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，钱德勒和莫妮卡还在争论如何告诉瑞秋钱德勒搬进来了，她搬出去了。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/125.mp3`}),c[512]||=i(),c[513]||=a(`strong`,null,`Chandler Bing:`,-1),c[514]||=i(` Okay, when are we gonna tell Rachel what is actually gonna happen?`,-1),c[515]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们什么时候告诉瑞秋到底会发生什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/126.mp3`}),c[516]||=i(),c[517]||=a(`strong`,null,`Monica Geller:`,-1),c[518]||=i(` Soon! I-I just couldn’t before. You saw how upset Joey got! I couldn’t do that to her, she’s my best friend!`,-1),c[519]||=a(`blockquote`,null,[a(`p`,null,`很快！我以前就是做不到。你看到乔伊有多生气了！我不能那样对她，她是我最好的朋友！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/127.mp3`}),c[520]||=i(),c[521]||=a(`strong`,null,`Chandler Bing:`,-1),c[522]||=i(` Well, Joey’s my best friend.`,-1),c[523]||=a(`blockquote`,null,[a(`p`,null,`乔伊是我最好的朋友。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/128.mp3`}),c[524]||=i(),c[525]||=a(`strong`,null,`Monica Geller:`,-1),c[526]||=i(` I’m not your best friend?`,-1),c[527]||=a(`blockquote`,null,[a(`p`,null,`我不是你最好的朋友？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/129.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`Chandler Bing:`,-1),c[530]||=i(` You just said… Of course you’re my best friend. Would you please tell Rachel though?`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`你刚才说…你当然是我最好的朋友。你能告诉瑞秋吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/130.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Monica Geller:`,-1),c[534]||=i(` All right, all right, at least I’m prepared.`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，至少我准备好了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/131.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Chandler Bing:`,-1),c[538]||=i(` Okay. (She grabs a tin of freshly baked cookies) Oh yes. (He reaches for one.)`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`好的。（她抓起一罐刚烤好的饼干）哦，是的。（他伸手去拿。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/132.mp3`}),c[540]||=i(),c[541]||=a(`strong`,null,`Monica Geller:`,-1),c[542]||=i(` (slapping his hand) Hey!`,-1),c[543]||=a(`blockquote`,null,[a(`p`,null,`（拍拍他的手）嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/133.mp3`}),c[544]||=i(),c[545]||=a(`strong`,null,`Chandler Bing:`,-1),c[546]||=i(` Hey-hey!`,-1),c[547]||=a(`blockquote`,null,[a(`p`,null,`嘿嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/134.mp3`}),c[548]||=i(),c[549]||=a(`strong`,null,`Monica Geller:`,-1),c[550]||=i(` These aren’t for you! Are you upset?`,-1),c[551]||=a(`blockquote`,null,[a(`p`,null,`这些不是给你的！你不高兴吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/135.mp3`}),c[552]||=i(),c[553]||=a(`strong`,null,`Chandler Bing:`,-1),c[554]||=i(` I am now!`,-1),c[555]||=a(`blockquote`,null,[a(`p`,null,`我现在是！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/136.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Rachel Green:`,-1),c[558]||=i(` (entering) Hey roomie!`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，室友！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/137.mp3`}),c[560]||=i(),c[561]||=a(`strong`,null,`Chandler Bing:`,-1),c[562]||=i(` Okay, bye! (Exits.)`,-1),c[563]||=a(`blockquote`,null,[a(`p`,null,`好的，再见！（退出。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/138.mp3`}),c[564]||=i(),c[565]||=a(`strong`,null,`Monica Geller:`,-1),c[566]||=i(` Rach, there’s something uh, important I have to tell you.`,-1),c[567]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，我有件很重要的事要告诉你。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/139.mp3`}),c[568]||=i(),c[569]||=a(`strong`,null,`Rachel Green:`,-1),c[570]||=i(` (gasps) Are you pregnant?!`,-1),c[571]||=a(`blockquote`,null,[a(`p`,null,`（喘息）你怀孕了吗？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/140.mp3`}),c[572]||=i(),c[573]||=a(`strong`,null,`Monica Geller:`,-1),c[574]||=i(` No! But, I’m throwing this shirt away! I think there was a little misunderstanding before.`,-1),c[575]||=a(`blockquote`,null,[a(`p`,null,`不！但是，我要把这件衬衫扔掉！我想以前有点误会。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/141.mp3`}),c[576]||=i(),c[577]||=a(`strong`,null,`Rachel Green:`,-1),c[578]||=i(` Um-hmm.`,-1),c[579]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/142.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Monica Geller:`,-1),c[582]||=i(` Umm, when I said that uh, that Chandler and I wanted to umm, live together we meant alone together.`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`嗯，当我说钱德勒和我想一起生活的时候，我们是指单独在一起。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/143.mp3`}),c[584]||=i(),c[585]||=a(`strong`,null,`Rachel Green:`,-1),c[586]||=i(` (laughs) Oh my God! Oh, that’s funny, I can’t believe I did that.`,-1),c[587]||=a(`blockquote`,null,[a(`p`,null,`（笑）哦，我的天啊！哦，真有趣，我不敢相信我做了那件事。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/144.mp3`}),c[588]||=i(),c[589]||=a(`strong`,null,`Monica Geller:`,-1),c[590]||=i(` Oh no sweetie, no! This is my fault, I wasn’t clear! I’m really sorry. And listen, you take as much time as you need to move out okay? There’s absolutely no rush.`,-1),c[591]||=a(`blockquote`,null,[a(`p`,null,`哦，不，亲爱的，不！这是我的错，我不清楚！我真的很抱歉。听着，你需要花多少时间搬出去，好吗？绝对不急。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/145.mp3`}),c[592]||=i(),c[593]||=a(`strong`,null,`Rachel Green:`,-1),c[594]||=i(` Okay. (Sits back and resumes her reading.)`,-1),c[595]||=a(`blockquote`,null,[a(`p`,null,`好的。（坐下来继续阅读。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/146.mp3`}),c[596]||=i(),c[597]||=a(`strong`,null,`Monica Geller:`,-1),c[598]||=i(` Okay. Don’t you want a cookie?`,-1),c[599]||=a(`blockquote`,null,[a(`p`,null,`好的。你不想吃饼干吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/147.mp3`}),c[600]||=i(),c[601]||=a(`strong`,null,`Rachel Green:`,-1),c[602]||=i(` Sure? (Monica hands her one.) Thanks.`,-1),c[603]||=a(`blockquote`,null,[a(`p`,null,`当然可以？（莫妮卡递给她一个）谢谢。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/148.mp3`}),c[604]||=i(),c[605]||=a(`strong`,null,`Monica Geller:`,-1),c[606]||=i(` Maybe, do you need a tissue?`,-1),c[607]||=a(`blockquote`,null,[a(`p`,null,`也许，你需要纸巾吗？`)],-1),c[608]||=a(`p`,null,[a(`em`,null,`(Rachel mumbles uh-huh and spits the half-eaten cookie out onto the tissue.)`)],-1),c[609]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋咕哝了一声，然后把吃了一半的饼干吐到纸巾上。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/149.mp3`}),c[610]||=i(),c[611]||=a(`strong`,null,`Rachel Green:`,-1),c[612]||=i(` Monica, where did you get these?!`,-1),c[613]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡，你从哪里弄来的？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/150.mp3`}),c[614]||=i(),c[615]||=a(`strong`,null,`Monica Geller:`,-1),c[616]||=i(` I made them!`,-1),c[617]||=a(`blockquote`,null,[a(`p`,null,`我做的！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/151.mp3`}),c[618]||=i(),c[619]||=a(`strong`,null,`Rachel Green:`,-1),c[620]||=i(` Ooh, good God, they’re so yummy! (She re-ingests the previously expelled cookie matter from the tissue.)`,-1),c[621]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，它们真好吃！（她重新摄取组织中先前排出的饼干物质。）`)],-1),c[622]||=a(`hr`,null,null,-1),c[623]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Chandler is packing some books and Joey is watching him.`)],-1),c[624]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，钱德勒正在打包书，乔伊在看着他。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/152.mp3`}),c[625]||=i(),c[626]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[627]||=i(` God, it’s gonna so weird like when I come home and you’re not here. Y’know? No more Joey and Chan’s. No more J and C’s. "You wanna go over to Joey and Chandler’s?" "Can’t, its not there."`,-1),c[628]||=a(`blockquote`,null,[a(`p`,null,`天啊，这会很奇怪，就像我回家你不在的时候。你知道吗？没有乔伊和陈的了。不再有J和C了。“你想去乔伊和钱德勒家吗？”“不行，不在那里。”`)],-1),r(p,{src:`/audio/friends/S06/S06E02/153.mp3`}),c[629]||=i(),c[630]||=a(`strong`,null,`Chandler Bing:`,-1),c[631]||=i(` Look, I’m just gonna be across the hall, we can still do all the same stuff.`,-1),c[632]||=a(`blockquote`,null,[a(`p`,null,`听着，我正要穿过大厅，我们仍然可以做同样的事情。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/154.mp3`}),c[633]||=i(),c[634]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[635]||=i(` Yeah but we won’t be able to like get up in the middle of the night and have those long talks about our feelings and the future.`,-1),c[636]||=a(`blockquote`,null,[a(`p`,null,`Joey：是的，但是我们不能喜欢在半夜起来谈论我们的感情和未来。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/155.mp3`}),c[637]||=i(),c[638]||=a(`strong`,null,`Chandler Bing:`,-1),c[639]||=i(` Not once did we do that.`,-1),c[640]||=a(`blockquote`,null,[a(`p`,null,`我们一次也没这么做。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/156.mp3`}),c[641]||=i(),c[642]||=a(`strong`,null,`Monica Geller:`,-1),c[643]||=i(` (entering) Hi.`,-1),c[644]||=a(`blockquote`,null,[a(`p`,null,`（进来）嗨。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/157.mp3`}),c[645]||=i(),c[646]||=a(`strong`,null,`Chandler Bing:`,-1),c[647]||=i(` Hey!`,-1),c[648]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/158.mp3`}),c[649]||=i(),c[650]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[651]||=i(` Hi.`,-1),c[652]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/159.mp3`}),c[653]||=i(),c[654]||=a(`strong`,null,`Monica Geller:`,-1),c[655]||=i(` So I, I told Rachel it was just gonna be the two of us.`,-1),c[656]||=a(`blockquote`,null,[a(`p`,null,`所以我，我告诉瑞秋，就我们俩。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/160.mp3`}),c[657]||=i(),c[658]||=a(`strong`,null,`Chandler Bing:`,-1),c[659]||=i(` Oh yeah? Well, how’d she take it?`,-1),c[660]||=a(`blockquote`,null,[a(`p`,null,`哦，是吗？那么，她觉得怎么样？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/161.mp3`}),c[661]||=i(),c[662]||=a(`strong`,null,`Monica Geller:`,-1),c[663]||=i(` Really well. Yeah. Surprisingly well. Yeah, she didn’t cry. She wasn’t angry or sad. (Sits down, slightly disgusted.)`,-1),c[664]||=a(`blockquote`,null,[a(`p`,null,`真的很好。是 啊出人意料地好。是的，她没有哭。她既不生气也不悲伤。（坐下来，有点恶心。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/162.mp3`}),c[665]||=i(),c[666]||=a(`strong`,null,`Chandler Bing:`,-1),c[667]||=i(` And you’re upset because you didn’t make your best friend cry?`,-1),c[668]||=a(`blockquote`,null,[a(`p`,null,`你不高兴是因为你没有让你最好的朋友哭？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/163.mp3`}),c[669]||=i(),c[670]||=a(`strong`,null,`Monica Geller:`,-1),c[671]||=i(` I mean, all I’m asking for is just a little emotion! Is that too much to ask after six years?! I mean what? Are-are-are Rachel and I not as close as you guys?! I mean do we not have as much fun?! Don’t I deserve a few tears?!! I mean we-we told Joey, he cried his eyes out!`,-1),c[672]||=a(`blockquote`,null,[a(`p`,null,`我的意思是，我所要求的只是一点点情感！六年后这要求太高了吗？！我是说什么？瑞秋和我不是像你们这么亲密吗？！我是说我们没有那么多乐趣吗？！难道我不该流泪吗？！！我是说，我们告诉乔伊，他哭得泪流满面！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/164.mp3`}),c[673]||=i(),c[674]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[675]||=i(` Hey! I did not cry my eyes out!! Come on! It’s like the end of an era! No more J-man and Channie’s!!`,-1),c[676]||=a(`blockquote`,null,[a(`p`,null,`嘿！我没有哭出来！！来吧这就像一个时代的结束！不再有J-man和Channie的了！！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/165.mp3`}),c[677]||=i(),c[678]||=a(`strong`,null,`Chandler Bing:`,-1),c[679]||=i(` Okay, I gotta ask, who calls us that?!`,-1),c[680]||=a(`blockquote`,null,[a(`p`,null,`好吧，我得问问，谁这么叫我们？！`)],-1),c[681]||=a(`hr`,null,null,-1),c[682]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross’s lawyer’s office, his name is Russell and has just been told by Ross about his current situation.`)],-1),c[683]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的律师办公室，他的名字叫拉塞尔，罗斯刚刚告诉他目前的情况。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/166.mp3`}),c[684]||=i(),c[685]||=a(`strong`,null,`Russell:`,-1),c[686]||=i(` You got married again.`,-1),c[687]||=a(`blockquote`,null,[a(`p`,null,`你又结婚了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/167.mp3`}),c[688]||=i(),c[689]||=a(`strong`,null,`Ross Geller:`,-1),c[690]||=i(` Yes.`,-1),c[691]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/168.mp3`}),c[692]||=i(),c[693]||=a(`strong`,null,`Russell:`,-1),c[694]||=i(` So that’s your second marriage in two years.`,-1),c[695]||=a(`blockquote`,null,[a(`p`,null,`这是你两年来的第二次婚姻。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/169.mp3`}),c[696]||=i(),c[697]||=a(`strong`,null,`Ross Geller:`,-1),c[698]||=i(` Yes, second in two years. Third overall.`,-1),c[699]||=a(`blockquote`,null,[a(`p`,null,`是的，两年内第二次。第三个整体。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/170.mp3`}),c[700]||=i(),c[701]||=a(`strong`,null,`Russell:`,-1),c[702]||=i(` Ross, I have been a divorce attorney for 23 years and never had I so much business from one client. Why don’t you tell me what happened.`,-1),c[703]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我做离婚律师已经23年了，从来没有和一个客户做过这么多生意。你为什么不告诉我发生了什么事。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/171.mp3`}),c[704]||=i(),c[705]||=a(`strong`,null,`Ross Geller:`,-1),c[706]||=i(` Basically, Rachel and I were in Vegas and we got drunk…`,-1),c[707]||=a(`blockquote`,null,[a(`p`,null,`基本上，瑞秋和我在维加斯喝醉了…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/172.mp3`}),c[708]||=i(),c[709]||=a(`strong`,null,`Russell:`,-1),c[710]||=i(` (interrupting) I’m sorry, is this the same Rachel who’s name you said at the altar in the second marriage?`,-1),c[711]||=a(`blockquote`,null,[a(`p`,null,`（打断一下）对不起，这就是你第二次结婚时在祭坛上说的瑞秋的名字吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/173.mp3`}),c[712]||=i(),c[713]||=a(`strong`,null,`Ross Geller:`,-1),c[714]||=i(` Yes-yes-yes! But, I-I do not love her.`,-1),c[715]||=a(`blockquote`,null,[a(`p`,null,`是的！但是，我不爱她。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/174.mp3`}),c[716]||=i(),c[717]||=a(`strong`,null,`Russell:`,-1),c[718]||=i(` Oh, that’s better then.`,-1),c[719]||=a(`blockquote`,null,[a(`p`,null,`哦，那就好了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/175.mp3`}),c[720]||=i(),c[721]||=a(`strong`,null,`Ross Geller:`,-1),c[722]||=i(` This was just a drunken mistake and I need to get it annulled.`,-1),c[723]||=a(`blockquote`,null,[a(`p`,null,`这只是一个醉酒的错误，我需要取消它。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/176.mp3`}),c[724]||=i(),c[725]||=a(`strong`,null,`Russell:`,-1),c[726]||=i(` I see. Have you considered therapy?`,-1),c[727]||=a(`blockquote`,null,[a(`p`,null,`我明白了。你考虑过治疗吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/177.mp3`}),c[728]||=i(),c[729]||=a(`strong`,null,`Ross Geller:`,-1),c[730]||=i(` I think just the annulment for today.`,-1),c[731]||=a(`blockquote`,null,[a(`p`,null,`我想只是今天的无效判决。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/178.mp3`}),c[732]||=i(),c[733]||=a(`strong`,null,`Russell:`,-1),c[734]||=i(` There are a couple of forms to fill out.`,-1),c[735]||=a(`blockquote`,null,[a(`p`,null,`有几张表格要填。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/179.mp3`}),c[736]||=i(),c[737]||=a(`strong`,null,`Ross Geller:`,-1),c[738]||=i(` Easy.`,-1),c[739]||=a(`blockquote`,null,[a(`p`,null,`简单。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/180.mp3`}),c[740]||=i(),c[741]||=a(`strong`,null,`Russell:`,-1),c[742]||=i(` And we’ll need to have witnesses who can testify that you were not of uh, sound mind.`,-1),c[743]||=a(`blockquote`,null,[a(`p`,null,`我们需要有证人来证明你精神不健全。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/181.mp3`}),c[744]||=i(),c[745]||=a(`strong`,null,`Ross Geller:`,-1),c[746]||=i(` No problem.`,-1),c[747]||=a(`blockquote`,null,[a(`p`,null,`没问题。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/182.mp3`}),c[748]||=i(),c[749]||=a(`strong`,null,`Russell:`,-1),c[750]||=i(` And we’ll need you and Rachel to testify before a judge.`,-1),c[751]||=a(`blockquote`,null,[a(`p`,null,`我们需要你和瑞秋在法官面前作证。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/183.mp3`}),c[752]||=i(),c[753]||=a(`strong`,null,`Ross Geller:`,-1),c[754]||=i(` Ooh! There’s no way to do this without her? ‘Cause I kinda all ready told her uh, it was, it was already taken care of.`,-1),c[755]||=a(`blockquote`,null,[a(`p`,null,`哦！没有她，这件事是办不到的？”因为我已经准备好了告诉她，呃，已经，已经处理好了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/184.mp3`}),c[756]||=i(),c[757]||=a(`strong`,null,`Russell:`,-1),c[758]||=i(` Of course you did. Look Ross, you can’t get an annulment unless you and Rachel are both there.`,-1),c[759]||=a(`blockquote`,null,[a(`p`,null,`你当然知道。听着，罗斯，除非你和瑞秋都在场，否则你不能解除合同。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/185.mp3`}),c[760]||=i(),c[761]||=a(`strong`,null,`Ross Geller:`,-1),c[762]||=i(` Uh-ha, what about someone who looks like Rachel? (Russell glares at him.) I will think about the therapy.`,-1),c[763]||=a(`blockquote`,null,[a(`p`,null,`嗯哈，长得像瑞秋的人呢？（拉塞尔瞪了他一眼）我会考虑治疗的。`)],-1),c[764]||=a(`hr`,null,null,-1),c[765]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Rachel is painting her toe nails as Monica enters.`)],-1),c[766]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，莫妮卡进来时瑞秋正在涂指甲油。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/186.mp3`}),c[767]||=i(),c[768]||=a(`strong`,null,`Rachel Green:`,-1),c[769]||=i(` Hey!`,-1),c[770]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/187.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Monica Geller:`,-1),c[773]||=i(` Hey. So um, I was thinking that maybe we should start dividing up our stuff.`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`嘿。所以，嗯，我在想也许我们应该开始把我们的东西分开。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/188.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Rachel Green:`,-1),c[777]||=i(` Okay!`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`好的！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/189.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Monica Geller:`,-1),c[781]||=i(` Y’know, no point in dragging it out. Dragging out the long process of you moving out and us not living together anymore.`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`你知道，拖拖拉拉是没有意义的。拖出你搬出去的漫长过程，我们不再住在一起。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/190.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Rachel Green:`,-1),c[785]||=i(` Okay.`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/191.mp3`}),c[787]||=i(),c[788]||=a(`strong`,null,`Monica Geller:`,-1),c[789]||=i(` Hey Rach, what about this? (She holds up a chrome 5-point star.) Huh? Who-who gets this? See, I don’t know if I want it because it might be y’know, too many memories!`,-1),c[790]||=a(`blockquote`,null,[a(`p`,null,`嘿，瑞秋，这个怎么样？（她举起一颗铬合金五点星）嗯？谁得到这个？看，我不知道我是否想要它，因为它可能是你知道的，太多的回忆了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/192.mp3`}),c[791]||=i(),c[792]||=a(`strong`,null,`Rachel Green:`,-1),c[793]||=i(` (grabbing the star) What the hell is that?`,-1),c[794]||=a(`blockquote`,null,[a(`p`,null,`（抓住星星）那到底是什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/193.mp3`}),c[795]||=i(),c[796]||=a(`strong`,null,`Monica Geller:`,-1),c[797]||=i(` I don’t know. (Picks up a big plate from the coffee table.) Hey, Rachel, you want the big plate? I want you to have the big plate.`,-1),c[798]||=a(`blockquote`,null,[a(`p`,null,`我不知道。（从咖啡桌上拿起一个大盘）嘿，瑞秋，你想要那个大盘吗？我要你拿一个大盘子。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/194.mp3`}),c[799]||=i(),c[800]||=a(`strong`,null,`Rachel Green:`,-1),c[801]||=i(` Wow! Mon, thanks! I love this plate!`,-1),c[802]||=a(`blockquote`,null,[a(`p`,null,`哇！妈妈，谢谢！我喜欢这个盘子！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/195.mp3`}),c[803]||=i(),c[804]||=a(`strong`,null,`Monica Geller:`,-1),c[805]||=i(` Something to remember me by!`,-1),c[806]||=a(`blockquote`,null,[a(`p`,null,`一些用来纪念我的东西！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/196.mp3`}),c[807]||=i(),c[808]||=a(`strong`,null,`Rachel Green:`,-1),c[809]||=i(` Mon, honey you’re not dying. I’m just moving out. Y’know, I mean we’re gonna see each other all the time.`,-1),c[810]||=a(`blockquote`,null,[a(`p`,null,`妈妈，亲爱的，你不会死的。我刚搬出去。我是说我们会一直见面的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/197.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Monica Geller:`,-1),c[813]||=i(` But still, it’s a big change. The end of an era, you might say!`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`但这仍然是一个很大的变化。你可能会说，一个时代的终结！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/198.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Rachel Green:`,-1),c[817]||=i(` Are you okay? You’re not blinking.`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`你没事吧？你没有眨眼。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/199.mp3`}),c[819]||=i(),c[820]||=a(`strong`,null,`Monica Geller:`,-1),c[821]||=i(` I’m fine! I just, I’m thinking how much it’s an end of era.`,-1),c[822]||=a(`blockquote`,null,[a(`p`,null,`我很好！我只是，我在想这是时代的终结。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/200.mp3`}),c[823]||=i(),c[824]||=a(`strong`,null,`Rachel Green:`,-1),c[825]||=i(` Oh, all right. But y’know I gotta say, I don’t, I don’t think six years counts as an era.`,-1),c[826]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧。但我得说，我不认为六年算不上一个时代。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/201.mp3`}),c[827]||=i(),c[828]||=a(`strong`,null,`Monica Geller:`,-1),c[829]||=i(` An era is defined as a significant period of time. Now, it was significant to me, maybe it wasn’t significant to you!`,-1),c[830]||=a(`blockquote`,null,[a(`p`,null,`时代是指一段重要的时间。现在，这对我来说很重要，也许对你来说并不重要！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/202.mp3`}),c[831]||=i(),c[832]||=a(`strong`,null,`Rachel Green:`,-1),c[833]||=i(` What is the matter with you?!`,-1),c[834]||=a(`blockquote`,null,[a(`p`,null,`你怎么了？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/203.mp3`}),c[835]||=i(),c[836]||=a(`strong`,null,`Monica Geller:`,-1),c[837]||=i(` What is the matter with you?!! Why aren’t you more upset?! Aren’t you gonna be sad that we’re not gonna be living together anymore?! I mean aren’t you gonna miss me at all?!`,-1),c[838]||=a(`blockquote`,null,[a(`p`,null,`你怎么了？！！你为什么不更难过？！我们再也不能住在一起了，你不会难过吧？！我是说你不会想念我吗？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/204.mp3`}),c[839]||=i(),c[840]||=a(`strong`,null,`Rachel Green:`,-1),c[841]||=i(` All right, fine, but don’t get mad at me. It’s-it’s just a little hard to believe.`,-1),c[842]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，但别生我的气。只是有点难以置信。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/205.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`Monica Geller:`,-1),c[845]||=i(` What’s hard to believe?`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`有什么难以置信的？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/206.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Rachel Green:`,-1),c[849]||=i(` Well y’know, it’s you guys. You-you do this kind of stuff! Y’know? I mean, you-you were gonna get married in Vegas and then you backed out! I guess I’m not upset because I don’t see you guys going through with it. I’m sorry.`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`你们知道，是你们。你做这种事！你知道吗？我是说，你要在维加斯结婚，然后你就退出了！我想我并不是因为看不到你们在经历这些而难过。我很抱歉。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/207.mp3`}),c[851]||=i(),c[852]||=a(`strong`,null,`Monica Geller:`,-1),c[853]||=i(` Rachel, it’s going to happen. Chandler is gonna move in here.`,-1),c[854]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，这会发生的。钱德勒要搬到这里来。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/208.mp3`}),c[855]||=i(),c[856]||=a(`strong`,null,`Rachel Green:`,-1),c[857]||=i(` But I…`,-1),c[858]||=a(`blockquote`,null,[a(`p`,null,`但是我…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/209.mp3`}),c[859]||=i(),c[860]||=a(`strong`,null,`Monica Geller:`,-1),c[861]||=i(` No-no, wait! Just let me finish, okay? This isn’t something that we just, we just impulsively decided in-in Vegas, this is something we both really want. And it is going to happen.`,-1),c[862]||=a(`blockquote`,null,[a(`p`,null,`不，不，等等！让我说完，好吗？这不是我们只是，我们只是在维加斯冲动地决定的，这是我们都真正想要的。而且它会发生的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/210.mp3`}),c[863]||=i(),c[864]||=a(`strong`,null,`Rachel Green:`,-1),c[865]||=i(` It is? Really?`,-1),c[866]||=a(`blockquote`,null,[a(`p`,null,`是吗？真正地`)],-1),r(p,{src:`/audio/friends/S06/S06E02/211.mp3`}),c[867]||=i(),c[868]||=a(`strong`,null,`Monica Geller:`,-1),c[869]||=i(` Yeah, sweetie.`,-1),c[870]||=a(`blockquote`,null,[a(`p`,null,`是的，亲爱的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/212.mp3`}),c[871]||=i(),c[872]||=a(`strong`,null,`Rachel Green:`,-1),c[873]||=i(` (starting to lose her composure) I mean we’re not, we’re not gonna live together anymore?`,-1),c[874]||=a(`blockquote`,null,[a(`p`,null,`（开始失去镇静）我是说我们不会，我们不会再住在一起了？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/213.mp3`}),c[875]||=i(),c[876]||=a(`strong`,null,`Monica Geller:`,-1),c[877]||=i(` No.`,-1),c[878]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/214.mp3`}),c[879]||=i(),c[880]||=a(`strong`,null,`Rachel Green:`,-1),c[881]||=i(` What? Oh my God! I’m gonna miss you so much! (Starts to cry.)`,-1),c[882]||=a(`blockquote`,null,[a(`p`,null,`什么？哦，我的上帝！我会非常想念你的！（开始哭了起来。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/215.mp3`}),c[883]||=i(),c[884]||=a(`strong`,null,`Monica Geller:`,-1),c[885]||=i(` I’m gonna miss you! (They hug.)`,-1),c[886]||=a(`blockquote`,null,[a(`p`,null,`我会想你的！（他们拥抱。）`)],-1),r(p,{src:`/audio/friends/S06/S06E02/216.mp3`}),c[887]||=i(),c[888]||=a(`strong`,null,`Rachel Green:`,-1),c[889]||=i(` I mean it’s the end of an era!`,-1),c[890]||=a(`blockquote`,null,[a(`p`,null,`我是说这是一个时代的结束！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/217.mp3`}),c[891]||=i(),c[892]||=a(`strong`,null,`Monica Geller:`,-1),c[893]||=i(` I know!`,-1),c[894]||=a(`blockquote`,null,[a(`p`,null,`我知道！`)],-1),c[895]||=a(`hr`,null,null,-1),c[896]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The hallway, Ross is coming up the stairs as Phoebe leaves Joey and Chandler’s.`)],-1),c[897]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`走廊，菲比离开乔伊和钱德勒家时，罗斯上楼来。`)])],-1),r(p,{src:`/audio/friends/S06/S06E02/218.mp3`}),c[898]||=i(),c[899]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[900]||=i(` (to Joey and Chandler) Okay, bye!`,-1),c[901]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊和钱德勒）好的，再见！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/219.mp3`}),c[902]||=i(),c[903]||=a(`strong`,null,`Ross Geller:`,-1),c[904]||=i(` Oh no.`,-1),c[905]||=a(`blockquote`,null,[a(`p`,null,`哦，不。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/220.mp3`}),c[906]||=i(),c[907]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[908]||=i(` So? Did you get the annulment?`,-1),c[909]||=a(`blockquote`,null,[a(`p`,null,`那么？你被判无效了吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/221.mp3`}),c[910]||=i(),c[911]||=a(`strong`,null,`Ross Geller:`,-1),c[912]||=i(` I couldn’t.`,-1),c[913]||=a(`blockquote`,null,[a(`p`,null,`我不能。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/222.mp3`}),c[914]||=i(),c[915]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[916]||=i(` I knew it! Because you love Rachel.`,-1),c[917]||=a(`blockquote`,null,[a(`p`,null,`我就知道！因为你爱瑞秋。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/223.mp3`}),c[918]||=i(),c[919]||=a(`strong`,null,`Ross Geller:`,-1),c[920]||=i(` It’s not that. Okay? Annulments are more complicated than I…`,-1),c[921]||=a(`blockquote`,null,[a(`p`,null,`不是那样的。可以环空比我想象的更复杂…`)],-1),r(p,{src:`/audio/friends/S06/S06E02/224.mp3`}),c[922]||=i(),c[923]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[924]||=i(` Yeah, complicated ‘cause of the love.`,-1),c[925]||=a(`blockquote`,null,[a(`p`,null,`是啊，因为爱而复杂。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/225.mp3`}),c[926]||=i(),c[927]||=a(`strong`,null,`Ross Geller:`,-1),c[928]||=i(` I… I do, I do not love Rachel. I’m gonna tell her right now about the whole thing so we can get this marriage annulled as fast as possible. Okay? Would I do that if I loved her?`,-1),c[929]||=a(`blockquote`,null,[a(`p`,null,`我…我爱，我不爱瑞秋。我现在就告诉她整件事，这样我们就能尽快取消这桩婚姻。可以如果我爱她，我会那样做吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/226.mp3`}),c[930]||=i(),c[931]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[932]||=i(` I’ve never been more convinced of your love for her.`,-1),c[933]||=a(`blockquote`,null,[a(`p`,null,`我从来没有像现在这样相信你对她的爱。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/227.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Ross Geller:`,-1),c[936]||=i(` I do not have feelings for Rachel! Okay?! (He goes into her apartment.)`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`我对瑞秋没有感情！可以（他走进她的公寓。）`)],-1),c[938]||=a(`p`,null,`[Cut to Monica and Rachel’s as Ross walks through the door. Rachel is holding the chrome star and crying.]`,-1),c[939]||=a(`blockquote`,null,[a(`p`,null,`[罗斯进门时，切到莫妮卡和瑞秋家。瑞秋拿着铬合金星星哭了起来。]`)],-1),r(p,{src:`/audio/friends/S06/S06E02/228.mp3`}),c[940]||=i(),c[941]||=a(`strong`,null,`Ross Geller:`,-1),c[942]||=i(` Ohh, what’s wrong?!`,-1),c[943]||=a(`blockquote`,null,[a(`p`,null,`哦，怎么了？！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/229.mp3`}),c[944]||=i(),c[945]||=a(`strong`,null,`Rachel Green:`,-1),c[946]||=i(` Monica and Chandler are really moving in here and I have to move out and everything is changing.`,-1),c[947]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡和钱德勒真的要搬进来了，我得搬出去，一切都变了。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/230.mp3`}),c[948]||=i(),c[949]||=a(`strong`,null,`Ross Geller:`,-1),c[950]||=i(` Oh my—Come here! Come here! (He hugs her.) It’s okay. Everything’s gonna be okay.`,-1),c[951]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，过来！过来！（他拥抱她）没关系。一切都会好起来的。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/231.mp3`}),c[952]||=i(),c[953]||=a(`strong`,null,`Rachel Green:`,-1),c[954]||=i(` Thank you.`,-1),c[955]||=a(`blockquote`,null,[a(`p`,null,`谢谢你。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/232.mp3`}),c[956]||=t(` <strong>Ross Geller:</strong> Of course.<blockquote><p>当然。</p></blockquote><p><em>(Ross suddenly realizes something.)</em></p><blockquote><p><em>（罗斯突然意识到了一些事情。）</em></p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk, Joey and Phoebe are talking.</em></p><blockquote><p>🎬 <em>中央公园，乔伊和菲比正在谈话。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S06/S06E02/233.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[959]||=i(` So, Ross and Rachel got married, Monica and Chandler almost got married, do you think you and I should hook up?`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`罗斯和瑞秋结婚了，莫妮卡和钱德勒差一点就结婚了，你觉得你和我应该勾搭上吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/234.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[963]||=i(` Oh we do, but not just yet.`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`是的，但还不是现在。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/235.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[967]||=i(` Really?! Well, when?`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！什么时候？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/236.mp3`}),c[969]||=i(),c[970]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[971]||=i(` Okay umm, well, first Chandler and Monica will get married and be filthy rich by the way. Yeah. But it won’t work out.`,-1),c[972]||=a(`blockquote`,null,[a(`p`,null,`好吧，嗯，首先钱德勒和莫妮卡会结婚，顺便说一句，他们会非常富有。是 啊但这行不通。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/237.mp3`}),c[973]||=i(),c[974]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[975]||=i(` Wow.`,-1),c[976]||=a(`blockquote`,null,[a(`p`,null,`哇。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/238.mp3`}),c[977]||=i(),c[978]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[979]||=i(` I know. Then, I’m gonna marry Chandler for the money and you’ll marry Rachel and have the beautiful kids.`,-1),c[980]||=a(`blockquote`,null,[a(`p`,null,`我知道。然后，为了钱我会嫁给钱德勒，你会嫁给瑞秋，生下漂亮的孩子。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/239.mp3`}),c[981]||=i(),c[982]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[983]||=i(` Great!`,-1),c[984]||=a(`blockquote`,null,[a(`p`,null,`太好了！`)],-1),r(p,{src:`/audio/friends/S06/S06E02/240.mp3`}),c[985]||=i(),c[986]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[987]||=i(` But then we ditch those two and that’s when we get married. We’ll have Chandler’s money and Rachel’s kids and getting custody will be easy because of Rachel’s drinking problem.`,-1),c[988]||=a(`blockquote`,null,[a(`p`,null,`但后来我们抛弃了那两个，那就是我们结婚的时候了。我们有钱德勒的钱和瑞秋的孩子，因为瑞秋酗酒，监护权很容易获得。`)],-1),r(p,{src:`/audio/friends/S06/S06E02/241.mp3`}),c[989]||=i(),c[990]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[991]||=i(` Oh-oh, what about Ross?`,-1),c[992]||=a(`blockquote`,null,[a(`p`,null,`哦，罗斯呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E02/242.mp3`}),c[993]||=i(),c[994]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[995]||=i(` I don’t want to go into the whole thing, but umm, we have words and I kill him.`,-1),c[996]||=a(`blockquote`,null,[a(`p`,null,`我不想谈整件事，但是我们有话要说，我杀了他。`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};